R.append((7585135,
("Ensalada de puerro y papa", "Una ensalada vibrante y baja en grasa, hecha con puerros en un aderezo de yogur con hierbas, que da como resultado una sabrosa ensalada de papa sin mayonesa.", "6", "182 g",
 ["600 g de papitas nuevas pequeñas", "1 puerro grande (250 g), limpio y en rodajas finas", "200 g de yogur griego sin grasa (0 %)", "10 g de cebollino (y un poco más para decorar)", "25 g de perejil (y un poco más para decorar)", "1 cucharadita colmada de mostaza Dijon", "1 buena pizca de pimienta blanca"],
 ["Hierva las papas enteras de 15 a 20 minutos, hasta que estén justo cocidas. Enfríelas con agua fría y deje reposar 15 minutos para que se enfríen.", "Mientras tanto, ponga los puerros en un tazón con el yogur, el cebollino, el perejil, la mostaza y la pimienta. Mezcle bien para asegurarse de que todos los puerros queden cubiertos. Reserve en el refrigerador.", "Cuando las papas estén frías, córtelas por la mitad, mézclelas con el aderezo de yogur y espolvoree con más hierbas."],
 [FVH], []),
("سلطة الكراث والبطاطس", "سلطة نابضة بالحياة وقليلة الدسم مصنوعة من الكراث مع تتبيلة الزبادي بالأعشاب لتحضير سلطة بطاطس لذيذة خالية من المايونيز.", "6", "182 غ",
 ["600 غ من البطاطس الجديدة الصغيرة", "1 حبة كراث كبيرة (250 غ)، منظفة ومقطعة إلى شرائح رفيعة", "200 غ من الزبادي اليوناني الخالي من الدسم (0%)", "10 غ من الثوم المعمر (الشيف) (ورشة إضافية للتزيين)", "25 غ من البقدونس (ورشة إضافية للتزيين)", "1 ملعقة صغيرة مكدسة من خردل ديجون", "رشة كبيرة من الفلفل الأبيض"],
 ["اسلق البطاطس كاملة لمدة 15-20 دقيقة حتى تنضج بالكاد. انقلها إلى ماء بارد ثم ضعها جانبًا لتبرد لمدة 15 دقيقة.", "في هذه الأثناء، ضع الكراث في وعاء مع الزبادي والثوم المعمر والبقدونس والخردل والفلفل. اخلطها جيدًا للتأكد من تغطية كل الكراث. ضعها جانبًا في الثلاجة.", "عندما تبرد البطاطس، اقطعها إلى نصفين وقلّبها مع تتبيلة الزبادي ورشّ عليها المزيد من الأعشاب."],
 [FVH], [])))
R.append((7585778,
("Tortilla de maíz dulce con salsa", "Esta tortilla vibrante y llena de sabor es perfecta para el almuerzo o para una cena ligera. Esta receta fue seleccionada en colaboración con Slimming World.", "4", "371 g",
 ["6 huevos grandes", "1 lata de 340 g de granos de maíz dulce en agua, escurridos", "6 cebollas verdes, en rodajas finas", "1 pimiento verde, sin semillas y en cubitos", "1 pimiento rojo, sin semillas y en cubitos", "300 g de tomates, en cubitos", "1 chile rojo, sin semillas y en cubitos (opcional)", "1 cucharada de puré de tomate concentrado", "Jugo de 2 limas", "Aceite en aerosol bajo en calorías para cocinar", "Rúcula, para servir"],
 ["Bata los huevos en un tazón grande. Incorpore el maíz dulce, la mitad de las cebollas verdes y el pimiento verde, y sazone con pimienta.", "En un tazón pequeño, mezcle el pimiento rojo, los tomates, el chile (si lo usa) y el resto de las cebollas verdes. Mezcle el puré de tomate con el jugo de lima, incorpórelo a la salsa y sazone al gusto.", "Precaliente el grill a temperatura alta. Rocíe una sartén grande antiadherente con un par de pulverizaciones de aceite en aerosol bajo en calorías y colóquela a fuego medio-bajo. Vierta la mezcla de huevo y cocine de 5 a 6 minutos o hasta que la parte superior empiece a cuajar. Termine bajo el grill, hasta que el huevo esté bien cocido.", "Retire la tortilla de la sartén, deje enfriar, luego córtela en 8 porciones triangulares y sirva con la rúcula. O bien, puede guardar las porciones y la salsa en recipientes herméticos y refrigerarlas hasta por 2 días. Para un almuerzo para llevar al trabajo, ponga un puñado de rúcula en una fiambrera, cubra con 2 porciones de tortilla y una cucharada de salsa, luego cierre y refrigere hasta el momento de comer."],
 [], []),
("عجّة الذرة الحلوة مع الصلصة", "هذه العجّة النابضة بالحياة والمليئة بالنكهة مثالية للغداء أو لعشاء خفيف. تم اختيار هذه الوصفة بالشراكة مع Slimming World.", "4", "371 غ",
 ["6 بيضات كبيرة", "1 علبة (340 غ) من حبات الذرة الحلوة في الماء، مصفّاة", "6 حبات بصل أخضر، مقطعة إلى شرائح رفيعة", "1 حبة فلفل رومي أخضر، منزوعة البذور ومقطعة إلى مكعبات", "1 حبة فلفل رومي أحمر، منزوعة البذور ومقطعة إلى مكعبات", "300 غ من الطماطم، مقطعة إلى مكعبات", "1 حبة فلفل أحمر حار، منزوعة البذور ومقطعة إلى مكعبات (اختياري)", "1 ملعقة كبيرة من معجون الطماطم", "عصير ليمونتين خضراوين", "بخاخ طهي قليل السعرات", "جرجير، للتقديم"],
 ["اخفق البيض في وعاء خلط كبير. أضف الذرة الحلوة ونصف كمية البصل الأخضر والفلفل الرومي الأخضر مع التحريك، ثم تبّل بالفلفل.", "في وعاء صغير، اخلط الفلفل الرومي الأحمر والطماطم والفلفل الحار (إن استخدمته) وباقي البصل الأخضر. اخلط معجون الطماطم مع عصير الليمون الأخضر، ثم أضفه إلى الصلصة وحرّك وتبّل حسب الذوق.", "سخّن الشواية مسبقًا على درجة عالية. رشّ مقلاة كبيرة غير لاصقة ببخّتين من بخاخ الطهي قليل السعرات وضعها على نار متوسطة إلى هادئة. اسكب خليط البيض واطهه لمدة 5-6 دقائق أو حتى يبدأ وجهه في التماسك. أنهِ الطهي تحت الشواية حتى ينضج البيض تمامًا.", "أخرج العجّة من المقلاة واتركها تبرد، ثم قطّعها إلى 8 قطع مثلثة وقدّمها مع الجرجير. أو يمكنك وضع القطع والصلصة في علب محكمة الإغلاق وتبريدها لمدة تصل إلى يومين. لوجبة غداء تأخذها معك إلى العمل، ضع حفنة من الجرجير في علبة الغداء، وضع فوقها قطعتين من العجّة وملعقة من الصلصة، ثم أغلقها وبرّدها حتى وقت الأكل."],
 [], [])))
R.append((7585916,
("Tortillas picantes de cangrejo", "El pescado enlatado es un excelente recurso de la despensa. También puede usar salmón o atún enlatado.", "4", "298 g",
 ["1 cucharadita de aceite de colza", "1 cebolla, finamente picada", "2.5 cm de jengibre fresco, pelado y rallado", "1 diente de ajo, machacado", "1 cucharadita de hojuelas de chile rojo seco", "1 cucharadita de comino molido", "240 g de carne de cangrejo blanca cocida", "3 cucharadas de cilantro fresco, picado", "8 tortillas de harina pequeñas (aprox. 40 g cada una)", "100 g de hojas de ensalada variadas", "4 tomates medianos, en rodajas", "8 gajos de lima, para servir"],
 ["Caliente el aceite en una sartén antiadherente. Agregue la cebolla, el jengibre, el ajo, las hojuelas de chile y el comino, y fría de 2 a 3 minutos.", "Retire la sartén del fuego e incorpore la carne de cangrejo y el cilantro.", "Caliente las tortillas según las instrucciones del paquete.", "Ponga algunas hojas de ensalada y rodajas de tomate en cada tortilla. Cubra con la mezcla de cangrejo y un chorrito de lima."],
 ["Para calentar las tortillas, póngalas todas en una pila en una sartén seca a fuego medio, tome la de abajo y pásela arriba, y siga haciéndolo hasta que todas hayan estado un minuto en contacto con la sartén caliente. Puede repetir por el otro lado durante 30 segundos para que queden bien calientes pero suaves y flexibles.", FVH], []),
("تورتيلا السلطعون الحارة", "السمك المعلب احتياطي رائع في خزانة المؤن. يمكنك أيضًا استخدام السلمون أو التونة المعلبة.", "4", "298 غ",
 ["1 ملعقة صغيرة من زيت اللفت", "1 حبة بصل، مفرومة ناعمًا", "2.5 سم من الزنجبيل الطازج، مقشر ومبشور", "1 فص ثوم، مهروس", "1 ملعقة صغيرة من رقائق الفلفل الأحمر الحار المجفف", "1 ملعقة صغيرة من الكمون المطحون", "240 غ من لحم السلطعون الأبيض المطبوخ", "3 ملاعق كبيرة من الكزبرة الخضراء الطازجة، مفرومة", "8 أرغفة تورتيلا صغيرة من الدقيق (حوالي 40 غ لكل رغيف)", "100 غ من أوراق السلطة المشكلة", "4 حبات طماطم متوسطة، مقطعة إلى شرائح", "8 أرباع ليمون أخضر، للتقديم"],
 ["سخّن الزيت في مقلاة غير لاصقة. أضف البصل والزنجبيل والثوم ورقائق الفلفل الحار والكمون وقلّبها لمدة 2-3 دقائق.", "ارفع المقلاة عن النار وأضف لحم السلطعون والكزبرة الخضراء مع التحريك.", "دفّئ التورتيلا وفق تعليمات العبوة.", "ضع بعض أوراق السلطة وشرائح الطماطم على كل تورتيلا. ضع فوقها خليط السلطعون وقليلًا من عصير الليمون الأخضر."],
 ["لتدفئة التورتيلا، ضعها كلها فوق بعضها في مقلاة جافة على نار متوسطة، ثم خذ الرغيف السفلي وانقله إلى الأعلى، وكرر ذلك حتى يلامس كل رغيف المقلاة الساخنة لمدة دقيقة. يمكنك تكرار العملية على الجانب الآخر لمدة 30 ثانية لتصبح ساخنة جدًا مع بقائها طرية ومرنة.", FVH], [])))
R.append((7587856,
("Conchiglie con tomate asado y langostinos", "Ligero y sencillo, este plato es ideal para recibir invitados.", "3", "352 g",
 ["250 g de tomates cherry, partidos por la mitad", "225 g de pasta integral seca en forma de conchas, por ejemplo conchiglie", "2 cucharadas de aceite de oliva", "2 dientes de ajo, en rodajas", "100 g de langostinos tigre crudos, pelados", "un puñado de albahaca fresca, desgarrada", "pimienta negra recién molida"],
 ["Precaliente el horno a 200 ºC (gas 6).", "Coloque los tomates en una fuente apta para horno, sazone bien y hornee de 20 a 25 minutos, hasta que estén tiernos y empiecen a chamuscarse.", "Mientras tanto, cocine la pasta según las instrucciones del paquete. Escurra y regrese a la olla.", "Mientras tanto, caliente el aceite en una sartén antiadherente, agregue el ajo y fría 1 minuto, añada los langostinos y fría de 1 a 2 minutos más, hasta que se pongan rosados.", "Mezcle todos los ingredientes, agregue la albahaca y sazone bien con pimienta negra."],
 ["Si lo prefiere, puede usar mariscos mixtos congelados o camarones pequeños del Atlántico en lugar de langostinos tigre.", FVH], []),
("كونكيليه مع الطماطم المشوية وجمبري النمر", "طبق خفيف وبسيط، رائع لاستقبال الضيوف.", "3", "352 غ",
 ["250 غ من الطماطم الكرزية، مقطعة إلى نصفين", "225 غ من المعكرونة المجففة من القمح الكامل بأشكال مختلفة، مثل الكونكيليه", "2 ملعقة كبيرة من زيت الزيتون", "2 فص ثوم، مقطع إلى شرائح", "100 غ من جمبري النمر النيئ، مقشر", "حفنة من الريحان الطازج، ممزق", "فلفل أسود مطحون طازجًا"],
 ["سخّن الفرن مسبقًا على 200° مئوية (درجة الغاز 6).", "ضع الطماطم في طبق مقاوم للحرارة، وتبّلها جيدًا ثم اخبزها في الفرن لمدة 20-25 دقيقة حتى تلين وتبدأ في التفحّم.", "في هذه الأثناء، اطهُ المعكرونة وفق تعليمات العبوة. صفِّها وأعدها إلى القدر.", "وفي الوقت نفسه، سخّن الزيت في مقلاة غير لاصقة، وأضف الثوم وقلّبه لمدة دقيقة، ثم أضف الجمبري وقلّبه لمدة 1-2 دقيقة إضافية حتى يصبح ورديًا.", "اخلط جميع المكونات معًا، وأضف الريحان وتبّل جيدًا بالفلفل الأسود."],
 ["يمكنك استخدام المأكولات البحرية المشكلة المجمدة أو الجمبري الأطلسي الصغير بدلًا من جمبري النمر، إن أردت.", FVH], [])))
R.append((7591571,
("Bacalao al horno con costra de perejil y rábano picante", "Delicioso pescado blanco con una cobertura crujiente de hierbas.", "2", "192 g",
 ["1 cucharada de rábano picante cremoso", "1 rebanada de pan multigrano, hecha migas", "1 cucharada de perejil fresco, picado", "2 trozos gruesos de filete de bacalao de 125 g cada uno", "pimienta negra recién molida", "80 g de rúcula"],
 ["Precaliente el horno a 200 ºC (gas 6). Mezcle el rábano picante, las migas de pan y el perejil, sazone bien y presione sobre los filetes de bacalao.", "Colóquelos en una bandeja para hornear y hornee de 10 a 12 minutos, hasta que el pescado esté bien cocido. Sirva con ensalada de rúcula y un gajo de limón."],
 ["El análisis nutricional anterior incluye una sugerencia de presentación con rúcula.", "Esta cobertura queda muy bien con otros pescados, como eglefino, salmón, filetes de caballa o bagre de río.", "Para desmenuzar el pan, séquelo primero en el horno unos minutos antes de licuarlo.", FVH], []),
("سمك القد المخبوز بقشرة البقدونس والفجل الحار", "سمك أبيض لذيذ بطبقة مقرمشة من الأعشاب.", "2", "192 غ",
 ["1 ملعقة كبيرة من الفجل الحار الكريمي", "1 شريحة خبز بالحبوب (غرانري)، مفتتة", "1 ملعقة كبيرة من البقدونس الطازج، مفروم", "2 قطعة سميكة من فيليه سمك القد، 125 غ لكل قطعة", "فلفل أسود مطحون طازجًا", "80 غ من الجرجير"],
 ["سخّن الفرن مسبقًا على 200° مئوية (درجة الغاز 6). اخلط الفجل الحار وفتات الخبز والبقدونس، وتبّل جيدًا واضغط الخليط على شرائح سمك القد.", "ضعها على صينية خَبز واخبزها لمدة 10-12 دقيقة حتى ينضج السمك تمامًا. قدّمها مع سلطة الجرجير وربع ليمونة."],
 ["يتضمن التحليل الغذائي أعلاه اقتراح تقديم مع الجرجير.", "تناسب هذه الطبقة أنواعًا أخرى من السمك مثل الحدوق أو السلمون أو فيليه الماكريل أو سمك الكوبلر النهري.", "لتفتيت الخبز، جففه أولًا في الفرن لبضع دقائق قبل خلطه في الخلاط.", FVH], [])))
R.append((7594884,
("Fideos salteados con tofu", "Un plato sabroso, sin carne, con sabores picantes de jengibre y pimienta.", "4", "329 g",
 ["225 g de tofu firme en bloque", "aceite en aerosol", "2 chalotas largas, peladas y en rodajas", "2 pimientos naranjas, en rodajas", "1 trozo de 2.5 cm de jengibre fresco, finamente picado", "1 paquete de 225 g de mazorcas de maíz baby, zanahorias y vainas de chícharo (mangetout)", "225 g de brotes de soya (frijol)", "225 g de fideos listos para el wok", "1 cucharada de salsa de soya reducida en sal", "pimienta negra recién molida"],
 ["Escurra el tofu y séquelo con toallas de papel. Corte en trozos del tamaño de un bocado y sazone con pimienta negra recién molida.", "Caliente un wok antiadherente. Rocíe ligeramente con aceite y agregue el tofu. Saltee rápidamente a fuego alto, revolviendo hasta que se dore ligeramente. Pase a un plato.", "Agregue al wok las chalotas y los pimientos y saltee a fuego alto. Añada el jengibre, el maíz baby, las zanahorias y los chícharos, y saltee de 2 a 3 minutos. Agregue los brotes de soya y saltee 2 minutos.", "Incorpore los fideos y la salsa de soya hasta que se calienten. Regrese el tofu al wok y mezcle bien. Sirva de inmediato."],
 ["Para darle más sabor, agregue uno o dos dientes de ajo machacados o 1 cucharadita de cinco especias chinas en polvo.", "Puede usar 200 g de pollo, pavo o pescado en lugar del tofu.", "Use arroz para que esta receta sea sin gluten.", "Para una opción con más fibra, elija fideos integrales.", FVH], []),
("نودلز التوفو المقلية بالتحريك", "طبق لذيذ خالٍ من اللحوم بنكهات الزنجبيل الحار والفلفل.", "4", "329 غ",
 ["225 غ من التوفو المتماسك على شكل قالب", "بخاخ زيت", "2 حبة إشالوت طويلة، مقشرة ومقطعة إلى شرائح", "2 حبة فلفل رومي برتقالي، مقطعة إلى شرائح", "قطعة زنجبيل طازج بطول 2.5 سم، مفرومة ناعمًا", "1 عبوة (225 غ) من الذرة الصغيرة والجزر والبازلاء الخضراء المسطحة (مانجتو)", "225 غ من براعم الفاصوليا", "225 غ من النودلز الجاهزة للووك", "1 ملعقة كبيرة من صلصة الصويا قليلة الملح", "فلفل أسود مطحون طازجًا"],
 ["صفِّ التوفو وجففه بمناديل المطبخ الورقية. قطّعه إلى قطع بحجم اللقمة وتبّله بالفلفل الأسود المطحون طازجًا.", "سخّن ووكًا غير لاصق. رشّه برذاذ خفيف من الزيت وأضف التوفو. قلّبه بسرعة على نار عالية مع التحريك حتى يحمرّ قليلًا. انقله إلى طبق.", "أضف الإشالوت والفلفل الرومي إلى الووك وقلّبها على نار عالية. أضف الزنجبيل والذرة الصغيرة والجزر والبازلاء المسطحة، وقلّبها لمدة 2-3 دقائق. أضف براعم الفاصوليا وقلّبها لمدة دقيقتين.", "أضف النودلز وصلصة الصويا برفق حتى تسخن. أعد التوفو إلى الووك وحرّك جيدًا. قدّمه فورًا."],
 ["لمزيد من النكهة، أضف فصّ ثوم أو فصّين مهروسين أو 1 ملعقة صغيرة من مسحوق توابل الخمس الصينية.", "يمكنك استخدام 200 غ من الدجاج أو الديك الرومي أو السمك بدلًا من التوفو.", "استخدم الأرز لجعل هذه الوصفة خالية من الغلوتين.", "للحصول على خيار أغنى بالألياف، اختر نودلز القمح الكامل.", FVH], [])))
R.append((7595443,
("Pitas de pollo al estilo griego", "Tiras de pechuga de pollo jugosa marinadas con ajo, jugo de limón y orégano, rellenando pan pita con ensalada con menta y yogur con pepino.", "2", "388 g",
 ["250 g de pechuga de pollo, cortada en tiras", "1 cucharadita de orégano seco", "Jugo de ½ limón", "3 dientes de ajo, machacados", "1 buena molienda de pimienta negra", "50 g de pepino, en cubitos finos", "60 g de yogur estilo griego sin grasa (0 %)", "2 tomates frescos, en rodajas", "10 hojas de menta fresca, desgarradas", "80 g de hojas de ensalada", "2 cucharaditas de aceite de oliva", "2 panes pita integrales", "gajos de limón, para servir"],
 ["Mezcle las tiras de pollo, el orégano, el jugo de limón, el ajo y la pimienta negra, y deje reposar 10 minutos para que tome sabor.", "Mientras tanto, en un tazón mezcle el pepino y el yogur. Combine los tomates y la menta y mézclelos con las hojas de ensalada.", "Caliente el aceite en una sartén pequeña, agregue el pollo y mezcle bien para que se cocine de manera uniforme; debería tardar unos 4 minutos.", "Caliente el pan pita en una sartén seca o en una tostadora, córtelo por la mitad y ábralo para formar bolsillos. Rellene con la ensalada y el pollo, exprima jugo de los gajos de limón y rocíe con la mezcla de yogur y pepino."],
 ["Para una versión vegetariana, use rebanadas de berenjena y calabacín asadas a la parrilla o falafeles.", "También queda muy bien con tiras de cerdo o de pavo.", FVH], []),
("ساندويتشات الدجاج بالطريقة اليونانية في خبز البيتا", "شرائح من صدر الدجاج العصيري المتبّل بالثوم وعصير الليمون والأوريجانو، محشوة في خبز البيتا مع سلطة بالنعناع وزبادي بالخيار.", "2", "388 غ",
 ["250 غ من صدر الدجاج، مقطع إلى شرائح طويلة", "1 ملعقة صغيرة من الأوريجانو المجفف", "عصير نصف ليمونة", "3 فصوص ثوم، مهروسة", "طحنة جيدة من الفلفل الأسود", "50 غ من الخيار، مقطع إلى مكعبات صغيرة", "60 غ من الزبادي بالطريقة اليونانية الخالي من الدسم (0%)", "2 حبة طماطم طازجة، مقطعة إلى شرائح", "10 أوراق نعناع طازجة، ممزقة", "80 غ من أوراق السلطة", "2 ملعقة صغيرة من زيت الزيتون", "2 رغيف بيتا من القمح الكامل", "أرباع ليمون، للتقديم"],
 ["اخلط شرائح الدجاج مع الأوريجانو وعصير الليمون والثوم والفلفل الأسود، وضعها جانبًا لمدة 10 دقائق لتتشرب النكهات.", "في هذه الأثناء، اخلط في وعاء الخيار والزبادي. اخلط الطماطم والنعناع معًا ثم اخلطهما مع أوراق السلطة.", "سخّن الزيت في مقلاة صغيرة، وأضف الدجاج وقلّبه جيدًا لضمان النضج المتساوي، ويستغرق ذلك حوالي 4 دقائق.", "دفّئ خبز البيتا في مقلاة جافة أو محمصة خبز، ثم اقطعه إلى نصفين وافتحه لتكوين جيوب. احشه بالسلطة والدجاج، واعصر عليه عصير الليمون من الأرباع ورشّ عليه خليط الزبادي والخيار."],
 ["للحصول على نسخة نباتية، استخدم شرائح مشوية من الباذنجان والكوسا أو الفلافل.", "تناسب هذه الوصفة أيضًا شرائح لحم الخنزير أو الديك الرومي.", FVH], [])))
R.append((7599326,
("Quiche de puerro caramelizado", "Un quiche impresionante con masa filo, lleno de puerros cocidos lentamente y cubierto con un poco de queso de cabra. Sorprendentemente fácil de hacer y a la vez deliciosamente cremoso a queso.", "4", "150 g",
 ["1 cucharadita de aceite de colza", "2-3 puerros, picados (320 g ya limpios)", "5 pulverizaciones de aceite en aerosol", "2 hojas de masa filo, cortadas en 4 cuadros (80 g)", "2 huevos, batidos", "2 cucharadas de yogur griego sin grasa (0 %)", "1 buena molienda de pimienta negra, más otra para servir", "30 g de queso de cabra", "1 cucharada de cebollino picado"],
 ["Precaliente el horno a 180 °C (gas 4).", "Ponga el aceite en una sartén a fuego medio-bajo y luego agregue los puerros. Cocine de 15 a 20 minutos, revolviendo con frecuencia, hasta que estén blandos. Retire del fuego y reserve.", "Rocíe un molde para pastel o para tarta con aceite en aerosol, luego rocíe cada cuadro de masa y colóquelos en el molde, formando una estrella.", "Ponga los huevos, el yogur y la pimienta en un tazón y bata bien. Incorpore los puerros y vierta la mezcla en la base de masa. Espolvoree con el queso de cabra y hornee de 15 a 18 minutos, hasta que apenas cuaje.", "Esparza el cebollino y un poco de pimienta negra, y sirva."],
 ["Pruebe este quiche con diferentes verduras cocidas, como brócoli o pimientos dulces. También queda muy bien con verduras sobrantes.", "Sirva con una ensalada grande de acompañamiento para aumentar su consumo de verduras y hacer de este una comida más completa.", "Instrucciones para congelar: se puede congelar una vez cocido. Luego descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", FVH], []),
("كيش الكراث المكرمل", "كيش مميز بعجينة الفيلو محشو بالكراث المطهو ببطء ومغطى بقليل من جبن الماعز. سهل التحضير بشكل مدهش، ومع ذلك غني بنكهة الجبن اللذيذة.", "4", "150 غ",
 ["1 ملعقة صغيرة من زيت اللفت", "2-3 حبات كراث، مقطعة (320 غ بعد التنظيف)", "5 بخّات من بخاخ الزيت", "2 ورقة من عجينة الفيلو، مقطعة إلى 4 مربعات (80 غ)", "2 بيضة، مخفوقة", "2 ملعقة كبيرة من الزبادي اليوناني الخالي من الدسم (0%)", "طحنة جيدة من الفلفل الأسود، وطحنة إضافية للتقديم", "30 غ من جبن الماعز", "1 ملعقة كبيرة من الثوم المعمر (الشيف) المفروم"],
 ["سخّن الفرن مسبقًا على 180° مئوية (درجة الغاز 4).", "ضع الزيت في مقلاة على نار متوسطة إلى هادئة، ثم أضف الكراث. اطهه لمدة 15-20 دقيقة مع التحريك باستمرار حتى يلين. ارفعه عن النار وضعه جانبًا.", "رشّ قالب كيك أو فطيرة بالزيت، ثم رشّ كل مربع من العجين ورتّبها في القالب لتكوين شكل نجمة.", "ضع البيض والزبادي والفلفل في وعاء واخفقها جيدًا. أضف الكراث مع التحريك وضع الخليط في قاعدة العجين. رشّ عليه جبن الماعز واخبزه لمدة 15-18 دقيقة حتى يتماسك بالكاد.", "وزّع فوقه الثوم المعمر وقليلًا من الفلفل الأسود وقدّمه."],
 ["جرّب هذا الكيش مع خضار مطبوخة مختلفة، مثل البروكلي أو الفلفل الحلو. ويناسب أيضًا الخضار المتبقية.", "قدّمه مع طبق جانبي كبير من السلطة لزيادة تناولك للخضار وجعل هذه الوجبة أكثر إشباعًا.", "تعليمات التجميد: يمكن تجميده بعد الطهي. ثم أذبه في الثلاجة أو في الميكروويف وأعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", FVH], [])))
R.append((7605212,
("Curry de cordero", "Un plato delicioso lleno de sabores picantes.", "6", "319 g",
 ["2 cucharaditas de aceite de girasol", "400 g de cordero magro en cubos", "3 cebollas, picadas", "4 zanahorias, picadas", "2 latas de 400 g de tomates picados", "1 cucharada de puré de tomate concentrado", "2-3 cucharaditas de curry en polvo", "1-3 chiles Scotch bonnet, finamente picados (según qué tan picante lo desee)", "6 cm de jengibre fresco, rallado", "1 cucharadita rasa de pimienta de Jamaica", "1 cucharada de perejil picado", "1 cubito de caldo de verduras o de pollo bajo en sal", "1 litro de agua", "1 cucharada de cilantro picado"],
 ["Caliente el aceite en una olla y agregue el cordero y las cebollas. Cocine durante 5 minutos, revolviendo con frecuencia, hasta que empiecen a dorarse.", "Agregue todos los demás ingredientes, excepto el cilantro, revuelva y deje que hierva. Tape, reduzca el fuego y cocine a fuego lento suavemente de 2 a 2.5 horas, revolviendo con frecuencia, hasta que el cordero esté tierno. Agregue un poco más de agua si es necesario.", "Sirva espolvoreado con el cilantro."],
 ["Para una versión más baja en grasa, use muslos de pollo: se cocinarán más rápido, así que reduzca el tiempo de cocción en una hora.", "Tenga cuidado: los chiles Scotch bonnet pueden ser muy pequeños, ¡pero también son muy picantes!", "Instrucciones para congelar: se puede congelar una vez cocido. Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", FVH], []),
("كاري لحم الضأن", "طبق لذيذ مليء بالنكهات الحارة.", "6", "319 غ",
 ["2 ملعقة صغيرة من زيت عباد الشمس", "400 غ من لحم الضأن الخالي من الدهن، مقطع إلى مكعبات", "3 حبات بصل، مفرومة", "4 حبات جزر، مفرومة", "2 علبة (400 غ لكل علبة) من الطماطم المقطعة", "1 ملعقة كبيرة من معجون الطماطم", "2-3 ملاعق صغيرة من مسحوق الكاري", "1-3 حبات من فلفل سكوتش بونيت الحار، مفرومة ناعمًا (حسب درجة الحرارة التي تفضلها)", "6 سم من الزنجبيل الطازج، مبشور", "1 ملعقة صغيرة مستوية من البهار الجامايكي", "1 ملعقة كبيرة من البقدونس المفروم", "1 مكعب مرق خضار أو دجاج قليل الملح", "1 لتر من الماء", "1 ملعقة كبيرة من الكزبرة الخضراء المفرومة"],
 ["سخّن الزيت في قدر وأضف لحم الضأن والبصل. اطهِها لمدة 5 دقائق مع التحريك باستمرار حتى تبدأ في التحمير.", "أضف جميع المكونات الأخرى، عدا الكزبرة الخضراء، وحرّك واتركها تغلي. ضع الغطاء، واخفض النار واتركها على نار هادئة بلطف لمدة 2-2.5 ساعة مع التحريك باستمرار حتى يلين لحم الضأن. أضف قليلًا من الماء إذا لزم الأمر.", "قدّمه مع رشة من الكزبرة الخضراء."],
 ["للحصول على نسخة أقل دسمًا، استخدم أفخاذ الدجاج، فهي تنضج أسرع، لذا قلّل وقت الطهي بمقدار ساعة.", "انتبه، فقد تكون حبات فلفل سكوتش بونيت صغيرة جدًا، لكنها أيضًا شديدة الحرارة!", "تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه يذوب في الثلاجة أو في الميكروويف، ثم أعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", FVH], [])))
R.append((7607126,
("Sopa de espinaca y arroz", "Una sopa baja en calorías con arroz, para una comida completa o ideal como entrada de invierno.", "2", "559 g",
 ["1 cucharadita de aceite de colza", "1 cebolla pequeña, picada", "1 diente de ajo, machacado", "1 zanahoria, finamente picada", "100 g de arroz integral", "1 bolsa de 150 g de espinaca fresca o congelada", "900 ml de caldo de verduras bajo en sal", "2 cucharadas de crema ligera para cocinar (single cream)", "pimienta negra recién molida"],
 ["Caliente el aceite en una sartén mediana.", "Agregue la cebolla, el ajo y la zanahoria y fría de 3 a 4 minutos, hasta que empiecen a ablandarse.", "Incorpore el arroz, la espinaca y el caldo, deje que hierva y cocine a fuego lento suavemente durante 35 minutos, hasta que el arroz esté tierno. Pase a una licuadora o procesador de alimentos con la crema y abundante pimienta negra, licúe hasta que quede suave y regrese a la olla para recalentar."],
 ["Si usa espinaca congelada en lugar de fresca, solo necesitará 100 g.", "Si no usa la sopa de inmediato, es posible que deba agregar más caldo o agua al recalentarla, ya que se espesará con el tiempo.", "Instrucciones para congelar: congele en porciones y luego descongele en el microondas. Caliente hasta que esté muy caliente, revolviendo con frecuencia. Consuma de inmediato y deseche las sobras.", FVH], []),
("شوربة السبانخ والأرز", "شوربة قليلة السعرات مصنوعة مع الأرز لوجبة متكاملة، أو مثالية كمقبلات شتوية.", "2", "559 غ",
 ["1 ملعقة صغيرة من زيت اللفت", "1 حبة بصل صغيرة، مفرومة", "1 فص ثوم، مهروس", "1 حبة جزر، مفرومة ناعمًا", "100 غ من الأرز البني", "1 كيس (150 غ) من السبانخ الطازجة أو المجمدة", "900 مل من مرق الخضار قليل الملح", "2 ملعقة كبيرة من الكريمة الخفيفة (سينغل كريم)", "فلفل أسود مطحون طازجًا"],
 ["سخّن الزيت في مقلاة متوسطة.", "أضف البصل والثوم والجزر وقلّبها لمدة 3-4 دقائق حتى تبدأ في الليونة.", "أضف الأرز والسبانخ والمرق مع التحريك، واتركه يغلي ثم دعه على نار هادئة بلطف لمدة 35 دقيقة حتى يلين الأرز. انقله إلى الخلاط أو محضّر الطعام مع الكريمة وكمية وافرة من الفلفل الأسود، واخلطه حتى يصبح ناعمًا ثم أعده إلى القدر لإعادة التسخين."],
 ["إذا استخدمت السبانخ المجمدة بدلًا من الطازجة، فستحتاج إلى 100 غ فقط.", "إذا لم تستخدم الشوربة مباشرة، فقد تحتاج إلى إضافة مرق أو ماء إضافي عند إعادة التسخين لأنها ستثخن بعد فترة.", "تعليمات التجميد: جمّدها في حصص ثم أذبها في الميكروويف. سخّنها حتى تصبح ساخنة جدًا مع التحريك باستمرار. تناولها فورًا وتخلّص من أي بقايا.", FVH], [])))
R.append((7609589,
("Pastel helado de yogur en capas", "Las capas de yogur de frutas forman un colorido y delicioso pastel arcoíris congelado.", "12", "104 g",
 ["250 g de frutos rojos variados congelados", "450 g de yogur natural casi sin grasa", "2 cucharadas de edulcorante granulado", "250 g de pulpa de mango picada (1 mango grande, fresco y maduro, pelado y sin hueso; o use congelado)", "300 g de pulpa de kiwi (unos 3-4), pelados"],
 ["Ponga una cuarta parte de los frutos rojos congelados en el fondo de un molde para pan de 2 lb (aprox. 900 g) o un molde para pastel.", "Licúe el resto de los frutos rojos con 150 g de yogur y 1 cucharada de edulcorante, y extienda la mezcla sobre los frutos rojos en el fondo del molde. Nivele con una espátula y coloque en el congelador, asegurándose de que el molde esté nivelado, y deje de 1 a 1.5 horas.", "Licúe el mango con 200 g de yogur y extienda sobre los frutos rojos. Regrese el molde al congelador, asegurándose nuevamente de que esté nivelado. Congele otra hora o dos, hasta que esté sólido.", "Licúe el kiwi con 100 g de yogur y 1 cucharada de edulcorante, luego agregue a la capa superior, extendiéndola de manera uniforme sobre el mango. Cubra con plástico adherente y congele por lo menos 2 horas o toda la noche.", "Saque del congelador 15 minutos antes de desmoldar sobre un plato y cortar en rebanadas."],
 ["Pruebe con diferentes frutas de colores contrastantes.", "Si licúa fruta congelada con el yogur, se congelará más rápido que con fruta fresca.", "Para facilitar el corte, corte el pastel de yogur con un cuchillo de sierra. Sumerja el cuchillo en agua caliente y séquelo antes de cortar.", "Use una alternativa de soya en lugar del yogur para una opción vegana.", "Instrucciones para congelar: mantenga congelado. Dura 3 meses en el congelador.", FVH], []),
("كيك الزبادي المثلج متعدد الطبقات", "طبقات من زبادي الفاكهة تصنع كيك قوس قزح مجمدًا ملونًا ولذيذًا.", "12", "104 غ",
 ["250 غ من التوت المشكل المجمد", "450 غ من الزبادي الطبيعي شبه الخالي من الدسم", "2 ملعقة كبيرة من المُحلّي الحبيبي", "250 غ من لب المانجو المقطع (1 حبة مانجو كبيرة طازجة وناضجة، مقشرة ومنزوعة النواة – أو استخدم المجمدة)", "300 غ من لب الكيوي (حوالي 3-4 حبات)، مقشرة"],
 ["ضع ربع كمية التوت المجمد في قاع قالب خبز طويل أو قالب كيك سعته 2 رطل.", "اخلط باقي التوت في الخلاط مع 150 غ من الزبادي و1 ملعقة كبيرة من المُحلّي، ثم افرد الخليط فوق التوت في قاع القالب. سوِّه بملعقة مسطحة وضعه في الفريزر مع التأكد من استواء القالب، واتركه لمدة 1-1.5 ساعة.", "اخلط المانجو في الخلاط مع 200 غ من الزبادي ثم افرده فوق التوت. أعد القالب إلى الفريزر مع التأكد مجددًا من استوائه. جمّده ساعة أو ساعتين إضافيتين حتى يتجمد تمامًا.", "اخلط الكيوي في الخلاط مع 100 غ من الزبادي و1 ملعقة كبيرة من المُحلّي، ثم أضفه إلى الطبقة العليا وافرده بالتساوي فوق المانجو. غطِّه بغلاف التغليف البلاستيكي، ثم جمّده لمدة ساعتين على الأقل أو طوال الليل.", "أخرجه من الفريزر قبل 15 دقيقة من قلبه على طبق وتقطيعه."],
 ["جرّب استخدام فواكه مختلفة بألوان متباينة.", "إذا خلطت الفاكهة المجمدة مع الزبادي، فسيتجمد أسرع مما لو استخدمت فاكهة طازجة.", "لتسهيل الأمر، قطّع كيك الزبادي بسكين مسنن. اغمس السكين في ماء ساخن، ثم جففه قبل التقطيع.", "استخدم بديل الصويا بدلًا من الزبادي للحصول على خيار نباتي.", "تعليمات التجميد: أبقِه مجمدًا. يبقى صالحًا لمدة 3 أشهر في الفريزر.", FVH], [])))
R.append((7614740,
("Puré de zanahoria y nabo sueco", "Un sabroso plato de verduras que es una buena alternativa al puré de papa y aporta una de sus cinco porciones diarias de fruta y verdura.", "8", "104 g",
 ["450 g de zanahorias, peladas y picadas", "450 g de nabo sueco (rutabaga), pelado y picado", "25 g de margarina a base de aceite vegetal", "2 cucharadas de rábano picante cremoso", "pimienta negra recién molida"],
 ["Cocine juntas las zanahorias y el nabo sueco en una olla con agua hirviendo con sal de 20 a 25 minutos, hasta que estén tiernos.", "Escurra y regrese a la olla.", "Agregue la margarina y el rábano picante, haga un puré bien suave y sazone al gusto."],
 ["Para una versión sin lactosa, use 1 cucharada de aceite de oliva en lugar de mantequilla y mostaza Dijon en lugar de rábano picante.", "Puede prepararlo el día anterior y luego calentarlo en el microondas u hornearlo en una fuente apta para horno.", "Instrucciones para congelar: descongele y luego caliente en el microondas para servir.", FVH], []),
("هريس الجزر واللفت السويدي", "طبق خضار لذيذ وبديل جيد لهريس البطاطس، ويوفر إحدى حصصك الخمس اليومية من الفاكهة والخضار.", "8", "104 غ",
 ["450 غ من الجزر، مقشر ومقطع", "450 غ من اللفت السويدي (سويد)، مقشر ومقطع", "25 غ من السمن النباتي المصنوع من الزيوت النباتية", "2 ملعقة كبيرة من الفجل الحار الكريمي", "فلفل أسود مطحون طازجًا"],
 ["اطهُ الجزر واللفت السويدي معًا في قدر من الماء المغلي المملح لمدة 20-25 دقيقة حتى يلينا.", "صفِّهما وأعدهما إلى القدر.", "أضف السمن النباتي والفجل الحار، واهرس جيدًا وتبّل حسب الذوق."],
 ["للحصول على نسخة خالية من اللاكتوز، استخدم 1 ملعقة كبيرة من زيت الزيتون بدلًا من الزبدة وخردل ديجون بدلًا من الفجل الحار.", "يمكنك تحضيره في اليوم السابق لحاجتك إليه ثم تسخينه في الميكروويف أو خبزه في طبق مقاوم للحرارة.", "تعليمات التجميد: اتركه يذوب ثم سخّنه في الميكروويف للتقديم.", FVH], [])))
R.append((7616374,
("Muffins de pan de maíz y calabacín con salsa", "A toda la familia le encantarán estos mini muffins de maíz llenos de calabacín y cebolla, cubiertos con una salsa picante de tomate y menta.", "30", "50 g",
 ["2 cucharaditas de aceite de colza", "1 cebolla morada, finamente picada", "1 pimiento rojo, finamente picado", "1 calabacín, rallado", "1 cucharadita de orégano", "2 huevos, batidos", "200 ml de leche descremada", "2 cucharadas de yogur griego sin grasa (0 %)", "150 g de polenta", "150 g de harina integral", "1 cucharadita de polvo de hornear", "30 g de queso Cheddar maduro, rallado", "4 tomates (200 g), finamente picados", "1 chile verde, finamente picado", "3 ramitas de menta, picadas", "1 cucharadita de vinagre"],
 ["Precaliente el horno a 180 °C (gas 4) y unte con aceite (o rocíe) un molde para mini muffins.", "Ponga 1 cucharadita de aceite en una sartén con la cebolla y el pimiento rojo, y cocine de 6 a 7 minutos, hasta que se ablanden.", "Retire del fuego y agregue el calabacín y el orégano, mezcle y reserve.", "En un tazón, mezcle el huevo, la leche y el yogur. Luego incorpore la polenta, la harina y el polvo de hornear, mezcle de nuevo y después incorpore las verduras y el queso rallado.", "Distribuya con una cuchara en el molde para mini muffins o en mini capacillos de papel. Hornee de 15 a 20 minutos, hasta que se doren ligeramente.", "Mientras tanto, mezcle los tomates, el chile, la menta y el vinagre para preparar la salsa."],
 ["Puede usar otras verduras; pruebe con maíz o chícharos cocidos, o reemplace el calabacín por espinaca cocida.", "Si no tiene un molde para mini muffins, puede usar mini capacillos de papel."], []),
("مافن خبز الذرة بالكوسا مع الصلصة", "ستستمتع العائلة بأكملها بمافن الذرة الصغير هذا المليء بالكوسا والبصل والمغطى بصلصة طماطم حارة بالنعناع.", "30", "50 غ",
 ["2 ملعقة صغيرة من زيت اللفت", "1 حبة بصل أحمر، مفرومة ناعمًا", "1 حبة فلفل رومي أحمر، مفرومة ناعمًا", "1 حبة كوسا، مبشورة", "1 ملعقة صغيرة من الأوريجانو", "2 بيضة، مخفوقة", "200 مل من الحليب منزوع الدسم", "2 ملعقة كبيرة من الزبادي اليوناني الخالي من الدسم (0%)", "150 غ من دقيق الذرة الخشن (بولينتا)", "150 غ من دقيق القمح الكامل", "1 ملعقة صغيرة من البيكنج باودر", "30 غ من جبن الشيدر المعتق، مبشور", "4 حبات طماطم (200 غ)، مفرومة ناعمًا", "1 حبة فلفل أخضر حار، مفرومة ناعمًا", "3 أغصان نعناع، مفرومة", "1 ملعقة صغيرة من الخل"],
 ["سخّن الفرن مسبقًا على 180° مئوية (درجة الغاز 4) وادهن (أو رشّ) صينية مافن صغيرة بالزيت.", "ضع 1 ملعقة صغيرة من الزيت في مقلاة مع البصل والفلفل الرومي الأحمر واطهِهما لمدة 6-7 دقائق حتى يلينا.", "ارفعهما عن النار وأضف الكوسا والأوريجانو، واخلط وضعها جانبًا.", "في وعاء، اخلط البيض والحليب والزبادي معًا. ثم أضف دقيق الذرة الخشن والدقيق والبيكنج باودر مع التحريك، واخلط مرة أخرى ثم أضف الخضار والجبن المبشور مع التحريك.", "اسكب الخليط بالملعقة في صينية المافن الصغيرة أو في أكواب ورقية صغيرة. اخبزه لمدة 15-20 دقيقة حتى يحمرّ قليلًا.", "في هذه الأثناء، اخلط الطماطم والفلفل الحار والنعناع والخل لتحضير الصلصة."],
 ["يمكنك استخدام خضار مختلفة، جرّب الذرة أو البازلاء المطبوخة، أو استبدل الكوسا بالسبانخ المطبوخة.", "إذا لم تكن لديك صينية مافن صغيرة، فيمكنك استخدام أكواب ورقية صغيرة."], [])))
